import{GovernorCard}from"./GovernorCard.js";export function Timeline(n){if(0===n.length)return'<div class="no-results">No Governors found matching your criteria.</div>';return`\n        <div class="timeline-container">\n            <div class="timeline-nav-wrapper">\n                <div class="timeline-track"></div>\n                <div class="timeline-nav">\n                    ${n.map(n=>`\n        <div class="timeline-nav-item" data-target="gov-${n.originalIndex}" title="${n.name} (${n.appointmentDate.split(" ").pop()})">\n            <div class="timeline-dot"></div>\n            <div class="timeline-year-label">${n.appointmentDate.split(" ").pop()}</div>\n        </div>\n    `).join("")}\n                </div>\n            </div>\n            <div class="cards-grid">\n                ${n.map(n=>`\n        <div class="card-wrapper">\n            ${GovernorCard(n,n.originalIndex)}\n        </div>\n    `).join("")}\n            </div>\n        </div>\n    `}